/* Bootstrap 5 compatible lite bundle for Limitless CRM pages.
 * Provides the data-bs APIs used in this admin: dropdown, collapse and offcanvas.
 * It intentionally has no jQuery dependency, matching Bootstrap 5 behavior.
 */
(function () {
  'use strict';

  const DATA_KEY = '__crmBootstrapLite';

  function getSelectorFromTrigger(trigger) {
    const target = trigger.getAttribute('data-bs-target');
    if (target && target !== '#') return target;
    const href = trigger.getAttribute('href');
    if (href && href.startsWith('#')) return href;
    return null;
  }

  function getTarget(trigger) {
    const selector = getSelectorFromTrigger(trigger);
    if (!selector) return null;
    try { return document.querySelector(selector); } catch (error) { return null; }
  }

  function closeDropdown(dropdown) {
    if (!dropdown) return;
    dropdown.classList.remove('show');
    const toggle = dropdown.querySelector('[data-bs-toggle="dropdown"]');
    const menu = dropdown.querySelector('.dropdown-menu');
    toggle && toggle.classList.remove('show');
    toggle && toggle.setAttribute('aria-expanded', 'false');
    menu && menu.classList.remove('show');
  }

  function closeAllDropdowns(except) {
    document.querySelectorAll('.dropdown.show, .dropup.show, .dropend.show, .dropstart.show').forEach((dropdown) => {
      if (dropdown !== except) closeDropdown(dropdown);
    });
  }

  class Dropdown {
    constructor(element) { this._element = element; }
    toggle() {
      const dropdown = this._element.closest('.dropdown, .dropup, .dropend, .dropstart');
      if (!dropdown) return;
      const menu = dropdown.querySelector('.dropdown-menu');
      const isOpen = dropdown.classList.contains('show');
      closeAllDropdowns(dropdown);
      if (isOpen) {
        closeDropdown(dropdown);
      } else {
        dropdown.classList.add('show');
        this._element.classList.add('show');
        this._element.setAttribute('aria-expanded', 'true');
        menu && menu.classList.add('show');
      }
    }
    hide() { closeDropdown(this._element.closest('.dropdown, .dropup, .dropend, .dropstart')); }
    show() {
      const dropdown = this._element.closest('.dropdown, .dropup, .dropend, .dropstart');
      if (!dropdown) return;
      const menu = dropdown.querySelector('.dropdown-menu');
      closeAllDropdowns(dropdown);
      dropdown.classList.add('show');
      this._element.classList.add('show');
      this._element.setAttribute('aria-expanded', 'true');
      menu && menu.classList.add('show');
    }
    static getOrCreateInstance(element) {
      if (!element[DATA_KEY]) element[DATA_KEY] = {};
      return element[DATA_KEY].dropdown || (element[DATA_KEY].dropdown = new Dropdown(element));
    }
  }

  class Collapse {
    constructor(element) { this._element = element; }
    toggle() { this._element.classList.toggle('show'); }
    show() { this._element.classList.add('show'); }
    hide() { this._element.classList.remove('show'); }
    static getOrCreateInstance(element) {
      if (!element[DATA_KEY]) element[DATA_KEY] = {};
      return element[DATA_KEY].collapse || (element[DATA_KEY].collapse = new Collapse(element));
    }
  }

  function ensureBackdrop() {
    let backdrop = document.querySelector('.offcanvas-backdrop');
    if (!backdrop) {
      backdrop = document.createElement('div');
      backdrop.className = 'offcanvas-backdrop fade show';
      document.body.appendChild(backdrop);
      backdrop.addEventListener('click', () => Offcanvas.closeAll());
    }
    return backdrop;
  }

  class Offcanvas {
    constructor(element) { this._element = element; }
    show() {
      Offcanvas.closeAll(this._element);
      this._element.classList.add('show');
      this._element.style.visibility = 'visible';
      this._element.setAttribute('aria-modal', 'true');
      this._element.setAttribute('role', 'dialog');
      document.body.classList.add('overflow-hidden');
      ensureBackdrop();
    }
    hide() {
      this._element.classList.remove('show');
      this._element.style.visibility = 'hidden';
      this._element.removeAttribute('aria-modal');
      this._element.removeAttribute('role');
      document.body.classList.remove('overflow-hidden');
      const backdrop = document.querySelector('.offcanvas-backdrop');
      backdrop && backdrop.remove();
    }
    toggle() { this._element.classList.contains('show') ? this.hide() : this.show(); }
    static closeAll(except) {
      document.querySelectorAll('.offcanvas.show').forEach((canvas) => {
        if (canvas !== except) Offcanvas.getOrCreateInstance(canvas).hide();
      });
      if (!except) {
        const backdrop = document.querySelector('.offcanvas-backdrop');
        backdrop && backdrop.remove();
        document.body.classList.remove('overflow-hidden');
      }
    }
    static getOrCreateInstance(element) {
      if (!element[DATA_KEY]) element[DATA_KEY] = {};
      return element[DATA_KEY].offcanvas || (element[DATA_KEY].offcanvas = new Offcanvas(element));
    }
  }

  document.addEventListener('click', function (event) {
    const dropdownToggle = event.target.closest('[data-bs-toggle="dropdown"]');
    if (dropdownToggle) {
      event.preventDefault();
      Dropdown.getOrCreateInstance(dropdownToggle).toggle();
      return;
    }

    const collapseToggle = event.target.closest('[data-bs-toggle="collapse"]');
    if (collapseToggle) {
      event.preventDefault();
      const target = getTarget(collapseToggle);
      if (target) {
        Collapse.getOrCreateInstance(target).toggle();
        collapseToggle.setAttribute('aria-expanded', target.classList.contains('show') ? 'true' : 'false');
      }
      return;
    }

    const offcanvasToggle = event.target.closest('[data-bs-toggle="offcanvas"]');
    if (offcanvasToggle) {
      event.preventDefault();
      const target = getTarget(offcanvasToggle);
      if (target) Offcanvas.getOrCreateInstance(target).toggle();
      return;
    }

    const offcanvasDismiss = event.target.closest('[data-bs-dismiss="offcanvas"]');
    if (offcanvasDismiss) {
      event.preventDefault();
      const canvas = offcanvasDismiss.closest('.offcanvas');
      if (canvas) Offcanvas.getOrCreateInstance(canvas).hide();
      return;
    }

    if (!event.target.closest('.dropdown-menu, [data-bs-toggle="dropdown"]')) closeAllDropdowns();
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      closeAllDropdowns();
      Offcanvas.closeAll();
    }
  });

  window.bootstrap = window.bootstrap || {};
  window.bootstrap.Dropdown = Dropdown;
  window.bootstrap.Collapse = Collapse;
  window.bootstrap.Offcanvas = Offcanvas;
})();
